head.script:
var currentLoginType = "normal";
var isKakaoAuthenticated = false;

scwin.onpageload = function() {
var mode = $p.getParameter("mode");
var email = $p.getParameter("email");
var nickname = $p.getParameter("nickname");

console.log("onpageload - mode:", mode);

if (mode === "kakao" && email && nickname) {
currentLoginType = "kakao";
isKakaoAuthenticated = true;

var decodedEmail = decodeURIComponent(email);
var decodedNickname = decodeURIComponent(nickname);

// 데이터맵 설정
signup_dma.set("userName", decodedNickname);
signup_dma.set("email", decodedEmail);

// 직접 input 값도 설정 (강제)
setTimeout(function() {
name_input.setValue(decodedNickname);
email_input.setValue(decodedEmail);
loginTypeSelect.setValue("kakao");
scwin.refreshUI();
}, 100);

} else {
currentLoginType = "normal";
isKakaoAuthenticated = false;
}

scwin.refreshUI();
};

scwin.loginTypeSelect_onchange = function() {
currentLoginType = loginTypeSelect.getValue();
isKakaoAuthenticated = false;

if (currentLoginType === "kakao") {
signup_dma.set("userName", "");
signup_dma.set("email", "");
signup_dma.set("password", "");
signup_dma.set("passwordConfirm", "");
}

scwin.refreshUI();
};

scwin.refreshUI = function() {
console.log("refreshUI - currentLoginType:", currentLoginType);

// 라디오 버튼 강제 설정
loginTypeSelect.setValue(currentLoginType);

var isNormal = (currentLoginType==="normal");

// UI 표시/숨김
grp_kakao_info.setStyle("display", isNormal ? "none" : "block");
grp_kakao_auth.setStyle("display", (!isNormal && !isKakaoAuthenticated) ? "block" : "none");
grp_kakao_user_info.setStyle("display", (!isNormal && isKakaoAuthenticated) ? "block" : "none");

// 읽기전용 설정 - 다시 한번 강제 적용
setTimeout(function() {
name_input.setReadOnly(!isNormal);
email_input.setReadOnly(!isNormal);
}, 50);

btn_check.setStyle("display", isNormal ? "inline-block" : "none");
grp_pwd.setStyle("display", isNormal ? "block" : "none");
grp_pwd_confirm.setStyle("display", isNormal ? "block" : "none");
grp_agree.setStyle("display", isNormal ? "block" : "none");

if(isNormal) {
trigger1.setLabel("회원가입");
} else {
trigger1.setLabel("카카오 회원가입");
}
};

scwin.btn_kakao_auth_onclick = function() {
$c.sbm.execute(kakaoAuthProcess);
};

scwin.kakaoAuthProcess_submitdone = function(e) {
if(e.responseStatusCode===200 && e.responseJSON.success && e.responseJSON.loginUrl) {
location.href = e.responseJSON.loginUrl;
} else {
console.log("카카오 인증 URL 호출 실패");
}
};

scwin.trigger1_onclick = function() {
if(currentLoginType==="normal") {
// 일반 회원가입
signup_dma.set("loginType", "normal");
if(!scwin.validateNormal()) return;
$c.sbm.execute(signupProcess);
} else {
// 카카오 회원가입
signup_dma.set("loginType", "kakao");
if(!scwin.validateKakao()) return;
$c.sbm.execute(signupProcess);
}
};

scwin.btn_check_onclick = function() {
if(currentLoginType === "normal") {
console.log("이메일 중복검사 전 데이터:");
console.log("email:", signup_dma.get("email"));
$c.sbm.execute(emailCheck);
} else {
console.log("카카오 회원가입에서는 이메일 중복검사가 필요하지 않습니다.");
}
};

scwin.validateNormal = function() {
var u = signup_dma.get("userName"),
m = signup_dma.get("email"),
p = signup_dma.get("password"),
pc= signup_dma.get("passwordConfirm"),
d = signup_dma.get("subDomain");
if(!u||u.trim()===""){ console.log("이름을 입력해주세요"); return false; }
if(!m||m.trim()===""){ console.log("이메일을 입력해주세요"); return false; }
if(!p||p.trim()===""){ console.log("비밀번호를 입력해주세요"); return false; }
if(p.length<8){ console.log("비밀번호는 8자 이상이어야 합니다"); return false; }
if(p!==pc){ console.log("비밀번호가 일치하지 않습니다"); return false; }
if(!d||d.trim()===""){ console.log("테넌트ID를 입력해주세요"); return false; }
if(chk_agree.getValue()!=="Y"){ console.log("개인정보 동의가 필요합니다"); return false; }
return true;
};

scwin.validateKakao = function() {
var t = signup_dma.get("tenantName"),
d = signup_dma.get("subDomain");
if(!t||t.trim()===""){ console.log("회사명을 입력해주세요"); return false; }
if(!d||d.trim()===""){ console.log("테넌트ID를 입력해주세요"); return false; }
return true;
};

scwin.signupProcess_submitdone = function(e) {
if(e.responseStatusCode===200) {
console.log("회원가입 완료");
location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_main.xml";
} else {
console.log("회원가입 처리 중 오류 발생");
}
};

/* 이메일 중복검사 완료 */
scwin.emailCheck_submitdone = function(e) {
console.log("이메일 중복검사 응답:", e);

if (e.responseStatusCode === 200) {
// 서버에서 온 문자열 메시지를 바로 alert로 표시
window.alert(e.responseText);
} else {
window.alert("이메일 중복검사 중 오류가 발생했습니다.");
}
};
